'use strict';

// MODULES //

var without = require( '@stdlib/array/base/without' );


// MAIN //

/**
* Performs a reduction over a list of specified dimensions in an input ndarray and assigns results to a provided output ndarray.
*
* ## Notes
*
* -   The `views` and `strides` parameters are unused. Providing empty arrays for these parameters is recommended in order to ensure a monomorphic API.
*
* @private
* @param {Function} fcn - wrapper for a one-dimensional strided array reduction function
* @param {Array<Object>} arrays - ndarray descriptors
* @param {Array<Object>} views - initialized ndarray descriptors representing subarray views
* @param {Array<integer>} strides - loop dimension strides for the input ndarray
* @param {Function} strategy - input ndarray reshape strategy
* @param {Options} opts - function options
* @returns {void}
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var accessors = require( '@stdlib/array/base/accessors' );
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
* var gsum = require( '@stdlib/blas/ext/base/ndarray/gsum' );
*
* // Create data buffers:
* var xbuf = toAccessorArray( new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] ) );
* var ybuf = toAccessorArray( new Float64Array( [ 0.0 ] ) );
*
* // Define the array shapes:
* var xsh = [ 2, 2 ];
* var ysh = [];
*
* // Define the array strides:
* var sx = [ 2, 1 ];
* var sy = [ 0 ];
*
* // Define the index offsets:
* var ox = 0;
* var oy = 0;
*
* // Create an input ndarray descriptor:
* var x = {
*     'dtype': 'float64',
*     'data': xbuf,
*     'shape': xsh,
*     'strides': sx,
*     'offset': ox,
*     'order': 'row-major',
*     'accessors': accessors( xbuf ).accessors
* };
*
* // Create an output ndarray descriptor:
* var y = {
*     'dtype': 'float64',
*     'data': ybuf,
*     'shape': ysh,
*     'strides': sy,
*     'offset': oy,
*     'order': 'row-major',
*     'accessors': accessors( ybuf ).accessors
* };
*
* // Define a reshape strategy:
* function strategy( x ) {
*     return {
*         'dtype': x.dtype,
*         'data': x.data,
*         'shape': [ 4 ],
*         'strides': [ 1 ],
*         'offset': x.offset,
*         'order': x.order
*     };
* }
*
* // Perform a reduction:
* kernel( gsum, [ x, y ], [], [], strategy, {} );
*
* var v = y.data.get( 0 );
* // returns 10.0
*/
function kernel( fcn, arrays, views, strides, strategy, opts ) {
	var y = arrays[ 1 ];
	arrays[ 0 ] = strategy( arrays[ 0 ] );
	y.accessors[ 1 ]( y.data, y.offset, fcn( without( arrays, 1 ), opts ) );
}


// EXPORTS //

module.exports = kernel;
